-- Phase 2.2B.1: PostgreSQL requires a new enum value to be committed before
-- replacement functions may safely reference it. Supabase applies this file as SQL.
begin;
alter type public.research_feed_type add value if not exists 'JSON_FEED' after 'ATOM';
commit;

begin;
create or replace function public.complete_research_feed_fetch(p_actor_id uuid,p_project_id uuid,p_feed_source_id uuid,p_run_id uuid,p_lease_token uuid,p_request_url_hash text,p_status public.research_feed_run_status,p_feed_type public.research_feed_type,p_final_url text,p_http_status integer,p_response_bytes integer,p_etag text,p_last_modified text,p_items jsonb default '[]') returns public.research_feed_fetch_runs language plpgsql security definer set search_path='' as $$
declare s public.research_feed_sources;r public.research_feed_fetch_runs;j jsonb;u uuid;url_match uuid;content_match uuid;created_n int:=0;changed_n int:=0;dedup_n int:=0;skipped_n int:=0;seen_n int:=0;now_ts timestamptz:=clock_timestamp();cats text[];published timestamptz;source_updated timestamptz;begin
 if not public.research_actor_owns(p_actor_id,p_project_id) then raise exception 'not_found' using errcode='P0002';end if;if p_lease_token is null or p_items is null or p_status not in ('SUCCEEDED','NOT_MODIFIED') or p_response_bytes not between 0 and 5242880 or p_final_url is null or char_length(p_final_url)>4096 or p_final_url!~'^https?://[^[:space:]]+$' or(p_status='SUCCEEDED' and(p_http_status<>200 or p_feed_type not in ('RSS','ATOM','JSON_FEED')))or(p_status='NOT_MODIFIED' and(p_http_status<>304 or p_response_bytes<>0)) or p_etag~E'[\r\n]' or char_length(p_etag)>512 or p_last_modified~E'[\r\n]' or char_length(p_last_modified)>128 or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)>500 or pg_column_size(p_items)>5242880 or(p_status='NOT_MODIFIED' and jsonb_array_length(p_items)<>0) then raise exception 'INVALID_COMPLETION_PAYLOAD' using errcode='22023';end if;
 select * into s from public.research_feed_sources where project_id=p_project_id and id=p_feed_source_id for update;select * into r from public.research_feed_fetch_runs where project_id=p_project_id and feed_source_id=p_feed_source_id and id=p_run_id for update;
 if s.id is null or r.id is null or r.status<>'RUNNING' or s.fetch_lease_token_hash is distinct from encode(public.digest(p_lease_token::text,'sha256'),'hex') or s.fetch_lease_run_id is distinct from p_run_id or s.fetch_lease_expires_at<=now_ts or r.lease_expires_at<=now_ts or r.lease_token_hash<>encode(public.digest(p_lease_token::text,'sha256'),'hex') or s.fetch_lease_url_hash<>p_request_url_hash or s.configured_url_hash<>p_request_url_hash or r.request_url_hash<>p_request_url_hash then raise exception 'STALE_FETCH_LEASE';end if;
 if p_status='SUCCEEDED' then for j in select * from jsonb_array_elements(p_items) loop
  if(j->>'content_hash')!~'^[0-9a-f]{64}$' or(j->>'url_hash' is not null and(j->>'url_hash')!~'^[0-9a-f]{64}$')or char_length(j->>'title')>500 or char_length(j->>'summary_text')>20000 or char_length(j->>'content_text')>100000 or char_length(j->>'author_name')>500 or char_length(j->>'language')>50 or char_length(j->>'canonical_url')>4096 or jsonb_typeof(coalesce(j->'categories','[]'))<>'array' or jsonb_array_length(coalesce(j->'categories','[]'))>50 then raise exception 'INVALID_ITEM_PAYLOAD' using errcode='22023';end if;
  cats:=array(select value from jsonb_array_elements_text(coalesce(j->'categories','[]')) value);if exists(select 1 from unnest(cats)x where char_length(x)>100)then raise exception 'INVALID_ITEM_PAYLOAD' using errcode='22023';end if;begin published:=nullif(j->>'published_at','')::timestamptz;source_updated:=nullif(j->>'source_updated_at','')::timestamptz;exception when others then raise exception 'INVALID_ITEM_DATE' using errcode='22023';end;
  seen_n:=seen_n+1;perform pg_advisory_xact_lock(hashtextextended(p_project_id::text||':'||least(coalesce(j->>'url_hash',j->>'content_hash'),j->>'content_hash'),0));perform pg_advisory_xact_lock(hashtextextended(p_project_id::text||':'||greatest(coalesce(j->>'url_hash',j->>'content_hash'),j->>'content_hash'),0));
  url_match:=null;content_match:=null;select research_item_id into url_match from public.research_item_fingerprints where project_id=p_project_id and fingerprint_type='URL' and fingerprint_hash=j->>'url_hash';select research_item_id into content_match from public.research_item_fingerprints where project_id=p_project_id and fingerprint_type='CONTENT' and fingerprint_hash=j->>'content_hash';
  if url_match is not null and content_match is not null and url_match<>content_match then skipped_n:=skipped_n+1;continue;end if;u:=coalesce(url_match,content_match);
  if u is null then insert into public.research_items(project_id,canonical_url,title,summary_text,content_text,author_name,published_at,source_updated_at,language,categories,created_by)values(p_project_id,j->>'canonical_url',j->>'title',j->>'summary_text',j->>'content_text',j->>'author_name',published,source_updated,j->>'language',cats,p_actor_id)returning id into u;insert into public.research_item_fingerprints(project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_project_id,u,'CONTENT',j->>'content_hash');if j->>'url_hash' is not null then insert into public.research_item_fingerprints(project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_project_id,u,'URL',j->>'url_hash');end if;created_n:=created_n+1;
  else if url_match is not null and content_match is null then update public.research_items set title=j->>'title',summary_text=j->>'summary_text',content_text=j->>'content_text',author_name=j->>'author_name',published_at=published,source_updated_at=source_updated,language=j->>'language',categories=cats,last_seen_at=now_ts,content_changed_at=now_ts,updated_at=now_ts where project_id=p_project_id and id=u;insert into public.research_item_fingerprints(project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_project_id,u,'CONTENT',j->>'content_hash');changed_n:=changed_n+1;else update public.research_items set last_seen_at=now_ts,updated_at=now_ts where project_id=p_project_id and id=u;dedup_n:=dedup_n+1;if j->>'url_hash' is not null then insert into public.research_item_fingerprints(project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_project_id,u,'URL',j->>'url_hash')on conflict do nothing;end if;end if;end if;
  insert into public.research_feed_item_observations(project_id,feed_source_id,research_item_id,fetch_run_id,external_item_id,observed_url,source_published_at)values(p_project_id,p_feed_source_id,u,p_run_id,j->>'external_id',j->>'canonical_url',published)on conflict(project_id,feed_source_id,research_item_id)do update set fetch_run_id=excluded.fetch_run_id,last_seen_at=now_ts,observation_count=public.research_feed_item_observations.observation_count+1,updated_at=now_ts;
 end loop;end if;
 update public.research_feed_fetch_runs set status=p_status,completed_at=now_ts,duration_ms=greatest(0,(extract(epoch from(now_ts-started_at))*1000)::int),final_url=p_final_url,http_status=p_http_status,response_bytes=p_response_bytes,items_seen=seen_n,items_created=created_n,items_changed=changed_n,items_deduplicated=dedup_n,items_skipped=skipped_n where id=p_run_id returning * into r;
 update public.research_feed_sources set detected_feed_type=case when p_status='SUCCEEDED' then p_feed_type else detected_feed_type end,health_status='HEALTHY',last_checked_at=now_ts,last_success_at=now_ts,last_content_change_at=case when created_n+changed_n>0 then now_ts else last_content_change_at end,last_http_status=p_http_status,last_final_url=p_final_url,etag=case when p_status='SUCCEEDED' then nullif(p_etag,'') else etag end,last_modified=case when p_status='SUCCEEDED' then nullif(p_last_modified,'') else last_modified end,consecutive_failures=0,next_eligible_fetch_at=now_ts+interval '60 seconds',last_error_code=null,last_error_message=null,fetch_lease_token_hash=null,fetch_lease_run_id=null,fetch_lease_url_hash=null,fetch_lease_expires_at=null,updated_at=now_ts where id=p_feed_source_id and fetch_lease_token_hash=encode(public.digest(p_lease_token::text,'sha256'),'hex') and fetch_lease_run_id=p_run_id;return r;end$$;

create or replace function public.complete_global_research_feed_fetch(p_owner_id uuid,p_feed_source_id uuid,p_run_id uuid,p_lease_token uuid,p_request_url_hash text,p_status public.research_feed_run_status,p_feed_type public.research_feed_type,p_final_url text,p_http_status integer,p_response_bytes integer,p_etag text,p_last_modified text,p_items jsonb default '[]') returns public.research_feed_fetch_runs language plpgsql security definer set search_path='' as $$declare s public.research_feed_sources;r public.research_feed_fetch_runs;j jsonb;u uuid;url_match uuid;content_match uuid;ts timestamptz:=clock_timestamp();cats text[];begin select * into s from public.research_feed_sources where owner_id=p_owner_id and id=p_feed_source_id for update;select * into r from public.research_feed_fetch_runs where owner_id=p_owner_id and id=p_run_id and feed_source_id=p_feed_source_id for update;if s.id is null or r.id is null or r.status<>'RUNNING' or s.fetch_lease_run_id<>p_run_id or s.fetch_lease_token_hash<>encode(public.digest(p_lease_token::text,'sha256'),'hex') or r.lease_token_hash<>encode(public.digest(p_lease_token::text,'sha256'),'hex') or s.fetch_lease_url_hash<>p_request_url_hash or s.configured_url_hash<>p_request_url_hash or r.request_url_hash<>p_request_url_hash or s.fetch_lease_expires_at<=ts or r.lease_expires_at<=ts then raise exception 'STALE_FETCH_LEASE';end if;if p_status not in('SUCCEEDED','NOT_MODIFIED') or (p_status='SUCCEEDED' and p_feed_type not in ('RSS','ATOM','JSON_FEED')) or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)>500 then raise exception 'INVALID_COMPLETION';end if;if p_status='SUCCEEDED' then for j in select * from jsonb_array_elements(p_items) loop cats:=array(select value from jsonb_array_elements_text(coalesce(j->'categories','[]'))value);select research_item_id into url_match from public.research_item_fingerprints where owner_id=p_owner_id and fingerprint_type='URL' and fingerprint_hash=j->>'url_hash';select research_item_id into content_match from public.research_item_fingerprints where owner_id=p_owner_id and fingerprint_type='CONTENT' and fingerprint_hash=j->>'content_hash';if url_match is not null and content_match is not null and url_match<>content_match then continue;end if;u:=coalesce(url_match,content_match);if u is null then insert into public.research_items(owner_id,project_id,canonical_url,title,summary_text,content_text,author_name,published_at,source_updated_at,language,categories,created_by)values(p_owner_id,s.project_id,j->>'canonical_url',j->>'title',j->>'summary_text',j->>'content_text',j->>'author_name',nullif(j->>'published_at','')::timestamptz,nullif(j->>'source_updated_at','')::timestamptz,j->>'language',cats,p_owner_id)returning id into u;insert into public.research_item_fingerprints(owner_id,project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_owner_id,s.project_id,u,'CONTENT',j->>'content_hash');else update public.research_items set last_seen_at=ts,updated_at=ts where owner_id=p_owner_id and id=u;insert into public.research_item_fingerprints(owner_id,project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_owner_id,s.project_id,u,'CONTENT',j->>'content_hash')on conflict(owner_id,fingerprint_type,fingerprint_hash)do nothing;end if;if j->>'url_hash' is not null then insert into public.research_item_fingerprints(owner_id,project_id,research_item_id,fingerprint_type,fingerprint_hash)values(p_owner_id,s.project_id,u,'URL',j->>'url_hash')on conflict(owner_id,fingerprint_type,fingerprint_hash)do nothing;end if;insert into public.research_feed_item_observations(owner_id,project_id,feed_source_id,research_item_id,fetch_run_id,external_item_id,observed_url,source_published_at)values(p_owner_id,s.project_id,s.id,u,p_run_id,j->>'external_id',j->>'canonical_url',nullif(j->>'published_at','')::timestamptz)on conflict(owner_id,feed_source_id,research_item_id)do update set fetch_run_id=excluded.fetch_run_id,last_seen_at=ts,observation_count=public.research_feed_item_observations.observation_count+1,updated_at=ts;end loop;end if;update public.research_feed_fetch_runs set status=p_status,completed_at=ts,duration_ms=greatest(0,(extract(epoch from(ts-started_at))*1000)::int),final_url=p_final_url,http_status=p_http_status,response_bytes=p_response_bytes where id=p_run_id returning * into r;update public.research_feed_sources set detected_feed_type=case when p_status='SUCCEEDED' then p_feed_type else detected_feed_type end,health_status='HEALTHY',last_checked_at=ts,last_success_at=ts,last_scheduled_fetch_at=case when r.trigger_type='SCHEDULED' then ts else last_scheduled_fetch_at end,next_scheduled_fetch_at=case when enabled and scheduler_enabled then ts+make_interval(mins=>fetch_interval_minutes) end,etag=case when p_status='SUCCEEDED' then nullif(p_etag,'') else etag end,last_modified=case when p_status='SUCCEEDED' then nullif(p_last_modified,'') else last_modified end,consecutive_failures=0,last_error_code=null,last_error_message=null,fetch_lease_token_hash=null,fetch_lease_run_id=null,fetch_lease_url_hash=null,fetch_lease_expires_at=null,updated_at=ts where id=p_feed_source_id and fetch_lease_run_id=p_run_id;return r;end$$;

-- CREATE OR REPLACE retains ownership and existing ACLs; assert the trusted boundary.
do $$begin
  if has_function_privilege('authenticated', 'public.complete_research_feed_fetch(uuid,uuid,uuid,uuid,uuid,text,public.research_feed_run_status,public.research_feed_type,text,integer,integer,text,text,jsonb)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.complete_global_research_feed_fetch(uuid,uuid,uuid,uuid,text,public.research_feed_run_status,public.research_feed_type,text,integer,integer,text,text,jsonb)', 'EXECUTE') then
    raise exception 'trusted completion execute privilege broadened';
  end if;
end$$;
commit;
